import numpy as np
from scipy.optimize import minimize

class HybridGA:
    def __init__(self, budget=10000, dim=10, population_size=20, mutation_rate=0.1, crossover_rate=0.8):
        self.budget = budget
        self.dim = dim
        self.population_size = population_size
        self.mutation_rate = mutation_rate
        self.crossover_rate = crossover_rate
        self.lb = -5.0
        self.ub = 5.0
        self.x_opt = None
        self.f_opt = np.inf


    def _initialize_population(self):
        return np.random.uniform(self.lb, self.ub, size=(self.population_size, self.dim))

    def _evaluate_population(self, func, population):
        fitness = np.zeros(self.population_size)
        for i in range(self.population_size):
            fitness[i] = func(population[i])
            self.budget -= 1  # reduce the budget for each function call
            if fitness[i] < self.f_opt:
                self.f_opt = fitness[i]
                self.x_opt = population[i].copy()
            if self.budget <= 0:
                break # if the budget has ran out we can stop iterating through the rest of the functions
        return fitness

    def _selection(self, population, fitness):
        # Tournament selection
        selected_indices = []
        for _ in range(self.population_size):
            idx1, idx2 = np.random.choice(self.population_size, 2, replace=False)
            if fitness[idx1] < fitness[idx2]:
                selected_indices.append(idx1)
            else:
                selected_indices.append(idx2)
        return population[selected_indices]


    def _crossover(self, parents):
        offspring = []
        for i in range(0, self.population_size, 2):
            if np.random.rand() < self.crossover_rate and i + 1 < self.population_size:
                # One-point crossover
                crossover_point = np.random.randint(1, self.dim)
                parent1 = parents[i]
                parent2 = parents[i+1]
                offspring1 = np.concatenate((parent1[:crossover_point], parent2[crossover_point:]))
                offspring2 = np.concatenate((parent2[:crossover_point], parent1[crossover_point:]))
                offspring.extend([offspring1, offspring2])
            else:
                offspring.append(parents[i].copy())  # No crossover
                if i + 1 < self.population_size:
                    offspring.append(parents[i+1].copy())
        return np.array(offspring)[:self.population_size]  #Ensure the right size after possibly generating offspring fewer than population_size

    def _mutation(self, population):
        for i in range(self.population_size):
            for j in range(self.dim):
                if np.random.rand() < self.mutation_rate:
                    # Gaussian mutation
                    population[i, j] += np.random.normal(0, 0.5)
                    population[i, j] = np.clip(population[i, j], self.lb, self.ub)
        return population

    def _local_search(self, func, individual):
      if self.budget <=0:
        return individual, func(individual)

      result = minimize(lambda x: func(x), individual, method='L-BFGS-B', bounds=[(self.lb, self.ub) for _ in range(self.dim)], options={'maxiter': min(50, self.budget)}) # Limit the number of iterations to stay within budget

      if result.fun < self.f_opt:
          self.f_opt = result.fun
          self.x_opt = result.x.copy()

      self.budget -= result.nfev # Reduce budget
      return result.x, result.fun



    def __call__(self, func):
        population = self._initialize_population()
        fitness = self._evaluate_population(func, population)

        while self.budget > 0:

            # Genetic Algorithm Steps
            parents = self._selection(population, fitness)
            offspring = self._crossover(parents)
            mutated_offspring = self._mutation(offspring)

            # Local Search - apply local search to the best individual (or a few)
            best_idx = np.argmin(fitness) #get index of best individual
            best_individual = population[best_idx].copy()
            best_individual, best_fitness = self._local_search(func, best_individual)

            if best_fitness < self.f_opt:
                self.f_opt = best_fitness
                self.x_opt = best_individual.copy()


            # Evaluate offspring, replace the worst individuals in the population
            fitness_offspring = self._evaluate_population(func, mutated_offspring) # evaluate after mutation

            # Replace worst in the original population
            worst_indices = np.argsort(fitness)[:self.population_size]
            population[worst_indices] = mutated_offspring
            fitness[worst_indices] = fitness_offspring

        return self.f_opt, self.x_opt

import numpy as np
from scipy.optimize import minimize

class WaterDropletSearch:
    def __init__(self, budget=10000, dim=10, num_droplets=10, droplet_radius=1.0, exploration_rate=0.5):
        self.budget = budget
        self.dim = dim
        self.num_droplets = num_droplets
        self.droplet_radius = droplet_radius
        self.exploration_rate = exploration_rate  # Probability of exploration vs. exploitation
        self.lb = -5.0
        self.ub = 5.0
        self.x_opt = None
        self.f_opt = np.inf
        self.droplet_positions = None  # Initialize droplet positions
        self.droplet_fitness = None # Initialize droplet fitness

    def _initialize_droplets(self):
        self.droplet_positions = np.random.uniform(self.lb, self.ub, size=(self.num_droplets, self.dim))
        self.droplet_fitness = np.full(self.num_droplets, np.inf)

    def _evaluate_droplets(self, func):
        for i in range(self.num_droplets):
            if self.budget > 0:
                self.droplet_fitness[i] = func(self.droplet_positions[i])
                self.budget -= 1
                if self.droplet_fitness[i] < self.f_opt:
                    self.f_opt = self.droplet_fitness[i]
                    self.x_opt = self.droplet_positions[i].copy()
            else:
                break # if the budget has ran out we can stop iterating through the rest of the functions


    def _move_droplets(self, func):
        for i in range(self.num_droplets):
            if np.random.rand() < self.exploration_rate:
                # Exploration: Random movement within droplet_radius
                direction = np.random.uniform(-1, 1, size=self.dim)
                direction /= np.linalg.norm(direction)  # Normalize
                movement = direction * self.droplet_radius
                new_position = self.droplet_positions[i] + movement
                new_position = np.clip(new_position, self.lb, self.ub)

                # Evaluate new position
                if self.budget > 0:
                    new_fitness = func(new_position)
                    self.budget -= 1
                    if new_fitness < self.droplet_fitness[i]:
                        self.droplet_positions[i] = new_position
                        self.droplet_fitness[i] = new_fitness
                        if new_fitness < self.f_opt:
                            self.f_opt = new_fitness
                            self.x_opt = self.droplet_positions[i].copy()

            else:
                # Exploitation: Local search (gradient-based)
                if self.budget > 0:
                    result = minimize(lambda x: func(x), self.droplet_positions[i], method='L-BFGS-B', bounds=[(self.lb, self.ub) for _ in range(self.dim)], options={'maxiter': min(20, self.budget)}) # Limit the number of iterations to stay within budget

                    if result.fun < self.droplet_fitness[i]:
                        self.droplet_positions[i] = result.x
                        self.droplet_fitness[i] = result.fun
                        if result.fun < self.f_opt:
                            self.f_opt = result.fun
                            self.x_opt = result.x.copy()

                    self.budget -= result.nfev


    def __call__(self, func):
        self._initialize_droplets()
        self._evaluate_droplets(func)

        while self.budget > 0:
            self._move_droplets(func)
            self._evaluate_droplets(func)  # Re-evaluate after movement

        return self.f_opt, self.x_opt

import numpy as np

class EchoChamberOptimizer:
    def __init__(self, budget=10000, dim=10, num_agents=10, echo_intensity=0.1, communication_range=0.5, exploration_rate=0.2):
        self.budget = budget
        self.dim = dim
        self.num_agents = num_agents
        self.echo_intensity = echo_intensity  # How strongly agents are influenced by the best
        self.communication_range = communication_range  # Radius for local communication
        self.exploration_rate = exploration_rate  # Probability of random exploration
        self.agents = []
        self.fitnesses = []
        self.best_agent_index = None  # Index of the best agent
        self.f_opt = np.inf
        self.x_opt = None

    def initialize_agents(self, bounds):
        for _ in range(self.num_agents):
            x = np.random.uniform(bounds.lb, bounds.ub)
            self.agents.append(x)
            self.fitnesses.append(np.inf) # Initialize fitness to infinity

    def __call__(self, func):
        self.initialize_agents(func.bounds)
        evaluations = 0

        while evaluations < self.budget:
            # Evaluate agents
            for i in range(self.num_agents):
                if evaluations >= self.budget:
                    break
                f = func(self.agents[i])
                evaluations += 1
                self.fitnesses[i] = f

                if f < self.f_opt:
                    self.f_opt = f
                    self.x_opt = self.agents[i].copy()
                    self.best_agent_index = i

            # Agent Movement and Communication
            for i in range(self.num_agents):
                # Echo effect (move towards the best)
                if i != self.best_agent_index:
                    self.agents[i] = self.agents[i] + self.echo_intensity * (self.agents[self.best_agent_index] - self.agents[i])

                # Local Communication/Neighborhood Search
                for j in range(self.num_agents):
                    if i != j:
                        distance = np.linalg.norm(self.agents[i] - self.agents[j])
                        if distance < self.communication_range:
                            # Move i closer to j if j is better, weighted by fitness difference
                            if self.fitnesses[j] < self.fitnesses[i]:
                                self.agents[i] = self.agents[i] + 0.05 * (self.agents[j] - self.agents[i])
                # Exploration
                if np.random.rand() < self.exploration_rate:
                    self.agents[i] = np.random.uniform(func.bounds.lb, func.bounds.ub)  # Random exploration

                #Apply Bounds
                self.agents[i] = np.clip(self.agents[i], func.bounds.lb, func.bounds.ub)


        return self.f_opt, self.x_opt
